class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;              // pure virtual
    virtual std::string name() const { return "shape"; }
};

class Circle : public Shape {
public:
    explicit Circle(double radius) : radius_(radius) {}
    double area() const override { return 3.141592653589793 * radius_ * radius_; }
    std::string name() const override { return "circle"; }

private:
    double radius_;
};

class Square : public Shape {
public:
    explicit Square(double side) : side_(side) {}
    double area() const override { return side_ * side_; }
    std::string name() const override { return "square"; }

private:
    double side_;
};

int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(2.0));
    shapes.push_back(std::make_unique<Square>(3.0));

    double total = 0.0;
    for (const auto& shape : shapes) {
        std::cout << shape->name() << ' ';
        total += shape->area();                   // virtual dispatch
    }
    std::cout << total << '\n';

    return total > 21.5 ? 0 : 1;                  // 12.566 + 9
}

#include <concepts>
#include <cstddef>
#include <type_traits>

template <typename T>
T clamp_value(T value, T low, T high) {
    return value < low ? low : (value > high ? high : value);
}

template <typename T>
concept Numeric = std::is_arithmetic_v<T>;

template <Numeric T>
T average(const T* data, std::size_t count) {
    T sum{};
    for (std::size_t i = 0; i < count; ++i) {
        sum += data[i];
    }
    return count == 0 ? T{} : sum / static_cast<T>(count);
}

int main() {
    int capped = clamp_value(15, 0, 10);          // 10
    double values[3] = {1.0, 2.0, 6.0};
    double mean = average(values, 3);             // 3.0

    return (capped == 10 && mean == 3.0) ? 0 : 1;
}

