template <typename T>
class Stack {
public:
    void push(const T& value) { items_.push_back(value); }

    T pop() {
        if (items_.empty()) {
            throw std::out_of_range("Stack::pop on empty stack");
        }
        T value = items_.back();
        items_.pop_back();
        return value;
    }

    bool empty() const { return items_.empty(); }
    std::size_t size() const { return items_.size(); }

private:
    std::vector<T> items_;
};

int main() {
    Stack<int> stack;
    stack.push(1);
    stack.push(2);
    return (stack.pop() == 2 && stack.size() == 1) ? 0 : 1;
}

