class Widget {
public:
    explicit Widget(std::string name) : name_(std::move(name)) {}
    ~Widget() { std::cout << "destroyed " << name_ << '\n'; }
    const std::string& name() const { return name_; }

private:
    std::string name_;
};

int main() {
    // Exclusive ownership, no delete required
    std::unique_ptr<Widget> owner = std::make_unique<Widget>("one");

    // Shared ownership
    std::shared_ptr<Widget> shared = std::make_shared<Widget>("two");
    std::shared_ptr<Widget> copy = shared;
    std::cout << "uses: " << shared.use_count() << '\n';   // 2

    // Non-owning observer, does not keep the object alive
    std::weak_ptr<Widget> observer = shared;
    if (auto locked = observer.lock()) {
        std::cout << "alive: " << locked->name() << '\n';
    }

    shared.reset();
    copy.reset();
    std::cout << "expired: " << std::boolalpha << observer.expired() << '\n';

    return observer.expired() ? 0 : 1;
}

