class Buffer {
public:
    explicit Buffer(std::size_t size) : data_(size, 0) {}

    // Move constructor: steals the storage, leaves the source valid
    Buffer(Buffer&& other) noexcept : data_(std::move(other.data_)) {}

    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            data_ = std::move(other.data_);
        }
        return *this;
    }

    Buffer(const Buffer&) = default;
    Buffer& operator=(const Buffer&) = default;

    std::size_t size() const { return data_.size(); }

private:
    std::vector<int> data_;
};

int main() {
    Buffer source(1000);
    Buffer target(std::move(source));

    std::vector<Buffer> buffers;
    buffers.push_back(Buffer(10));   // moved, not copied
    buffers.emplace_back(20);        // constructed in place

    std::cout << target.size() << ' ' << source.size() << '\n';
    return (target.size() == 1000 && buffers.size() == 2) ? 0 : 1;
}

