        throw std::domain_error("division by zero");
    }
    return numerator / denominator;
}

int main() {
    try {
        double result = divide(10.0, 0.0);
        std::cout << result << '\n';
    } catch (const std::domain_error& error) {
        std::cerr << "domain error: " << error.what() << '\n';
    } catch (const std::exception& error) {
        std::cerr << "error: " << error.what() << '\n';
    }
    return 0;
}

#include <stdexcept>
#include <string>

class ParseError : public std::runtime_error {
public:
    explicit ParseError(const std::string& input)
        : std::runtime_error("cannot parse: " + input) {}
};

int parse_positive(const std::string& text) {
    std::size_t consumed = 0;
    int value = std::stoi(text, &consumed);   // may throw std::invalid_argument
    if (consumed != text.size() || value <= 0) {
        throw ParseError(text);
    }
    return value;
}

int main() noexcept {
    try {
        parse_positive("12x");
        return 1;                    // not reached for this input
    } catch (const ParseError&) {
        return 0;                    // trailing text rejected as expected
    } catch (const std::exception&) {
        return 2;
    }
}

