struct Base {
    virtual ~Base() = default;
};

struct Derived : Base {
    int extra = 7;
};

int main() {
    // Slicing: copying into a Base value drops the Derived part
    Derived derived;
    Base sliced = derived;               // wrong: extra is lost
    Base& polymorphic = derived;         // right: keeps the dynamic type

    // Ownership: prefer smart pointers over manual new/delete
    auto owned = std::make_unique<Derived>();   // no delete needed

    // Iterator invalidation: re-acquire after a structural change
    std::vector<int> values{1, 2, 3};
    values.push_back(4);                 // may reallocate
    auto first = values.begin();         // re-acquire after push_back

    std::cout << "first: " << *first << '\n';
    return (*first == 1 && owned != nullptr) ? 0 : 1;
}

#include <cstddef>
#include <iostream>
#include <memory>
#include <vector>

int main() {
    // Uninitialized local: always give a value
    int count = 0;                       // int count; holds an indeterminate value

    // Signed/unsigned: use size_t for sizes and cast explicitly
    std::vector<int> values{1, 2, 3};
    for (std::size_t i = 0; i < values.size(); ++i) {
        count += values[i];
    }

    // Double delete and leaks: let one owner destroy the object
    auto buffer = std::make_unique<int[]>(4);
    buffer[0] = 9;

    std::cout << count << ' ' << buffer[0] << '\n';
    return count == 6 ? 0 : 1;
}
